  const encoded = sql.replace(/[+\-*/=]/g, (char) => {
    const charMap = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&#39;',
      '\'': '&#039;',
      '\r': '|',
      '\n': '|',
      ' ': '|',
      '$': '&#160;',
      '%': '&#162;',
    };
    return charMap[char] || char;
  });
  return encoded;
}

function decodeSQLi(encoded) {
  const decoded = encoded.replace(/[+*/=]/g, (char) => {
    const charMap = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&#39;',
      '\'': '&#039;',
    };
    return charMap[char] || char;
  });
  return decoded;
}
